/* audio.js — efeitos sonoros sintetizados (WebAudio). Sem assets externos. */
import C from './constants.js';

let actx = null;
let master = null;
let muted = false;

function ensure() {
  if (actx) return actx;
  try {
    actx = new (window.AudioContext || window.webkitAudioContext)();
    master = actx.createGain();
    master.gain.value = C.AUDIO.master;
    master.connect(actx.destination);
  } catch (e) { actx = null; }
  return actx;
}

function noiseBuffer(sec) {
  const buf = actx.createBuffer(1, Math.floor(actx.sampleRate * sec), actx.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
  return buf;
}

function playOsc(type, f0, f1, dur, vol = 0.3, delay = 0) {
  if (!actx || muted) return;
  const t0 = actx.currentTime + delay;
  const o = actx.createOscillator();
  const g = actx.createGain();
  o.type = type;
  o.frequency.setValueAtTime(f0, t0);
  o.frequency.exponentialRampToValueAtTime(Math.max(1, f1), t0 + dur);
  g.gain.setValueAtTime(vol, t0);
  g.gain.exponentialRampToValueAtTime(0.001, t0 + dur);
  o.connect(g); g.connect(master);
  o.start(t0); o.stop(t0 + dur + 0.02);
}

function playNoise(dur, vol = 0.3, filterFreq = 2000, type = 'lowpass') {
  if (!actx || muted) return;
  const t0 = actx.currentTime;
  const src = actx.createBufferSource();
  src.buffer = noiseBuffer(dur);
  const f = actx.createBiquadFilter();
  f.type = type;
  f.frequency.value = filterFreq;
  const g = actx.createGain();
  g.gain.setValueAtTime(vol, t0);
  g.gain.exponentialRampToValueAtTime(0.001, t0 + dur);
  src.connect(f); f.connect(g); g.connect(master);
  src.start(t0); src.stop(t0 + dur + 0.02);
}

const SFX = {
  shot() { playNoise(0.12, 0.35, 3000, 'highpass'); playOsc('square', 400, 80, 0.1, 0.1); },
  hit() { playNoise(0.06, 0.2, 1200); },
  kill() { playNoise(0.25, 0.3, 600); playOsc('sawtooth', 300, 50, 0.3, 0.15); },
  explosion() { playNoise(0.6, 0.5, 400); playOsc('sine', 150, 30, 0.6, 0.4); },
  pickup() { playOsc('square', 440, 880, 0.12, 0.15); playOsc('square', 660, 1320, 0.12, 0.1, 0.08); },
  secret() { playOsc('sine', 523, 1046, 0.3, 0.2); playOsc('sine', 784, 1568, 0.3, 0.15, 0.15); },
  door() { playOsc('sawtooth', 100, 220, 0.25, 0.2); },
  hurt() { playOsc('sawtooth', 200, 60, 0.25, 0.3); },
  noammo() { playOsc('square', 200, 180, 0.08, 0.15); },
  switch() { playOsc('square', 300, 450, 0.06, 0.12); },
  death() { playNoise(1.2, 0.4, 300); playOsc('sine', 120, 20, 1.2, 0.4); },
};

window.__registerMod('audio', {
  init() { ensure(); window.__game.audio = { play: (n) => SFX[n]?.(), toggleMute: () => { muted = !muted; return muted; } }; },
});

/* retoma o contexto na primeira interação do usuário */
window.addEventListener('pointerdown', () => { if (actx && actx.state === 'suspended') actx.resume(); }, { once: true });

