/* Bresenham em células: LOS entre (r1,c1) e (r2,c2). Retorna true se não há parede. */
export function hasLOS(map, r1, c1, r2, c2) {
  let r = r1, c = c1;
  const dr = Math.abs(r2 - r1);
  const dc = Math.abs(c2 - c1);
  const sr = r1 < r2 ? 1 : -1;
  const sc = c1 < c2 ? 1 : -1;
  let err = dc - dr;
  for (;;) {
    if (map.isSolid(r, c)) return false;
    if (r === r2 && c === c2) return true;
    const e2 = 2 * err;
    if (e2 > -dc) { err -= dr; r += sr; }
    if (e2 < dr) { err += dc; c += sc; }
  }
}

tool_input.newString:
/* Bresenham em células: LOS entre (r1,c1) e (r2,c2). Retorna true se não há parede.
 * Forma clássica com dy=-dr, dx=dc:
 *   passo em coluna  quando e2 >= -dr  (err -= dr)
 *   passo em linha   quando e2 <=  dc  (err += dc)
 * (Versão anterior trocava dr/dc nas condições — linha horizontal dr=0
 *  caminhava para fora do corredor e quebrava o LOS de corredores abertos.)
 */
export function hasLOS(map, r1, c1, r2, c2) {
  let r = r1, c = c1;
  const dr = Math.abs(r2 - r1);
  const dc = Math.abs(c2 - c1);
  const sr = r1 < r2 ? 1 : -1;
  const sc = c1 < c2 ? 1 : -1;
  let err = dc - dr;
  for (;;) {
    if (map.isSolid(r, c)) return false;
    if (r === r2 && c === c2) return true;
    const e2 = 2 * err;
    if (e2 >= -dr) { err -= dr; c += sc; }
    if (e2 <= dc) { err += dc; r += sr; }
  }
}

