/* level.js — constrói a geometria do nível a partir do grid puro (map.js).
 * 🎨 Render: usa Three.js (CanvasTexture, BufferGeometry, PointLight).
 * Exporta buildLevel(map, THREE) → { group, update, doorMeshes, exitPos, torchLights }.
 */
import { C } from './constants.js';

/* ---------------------------------------------------------------------------
 * Texturas procedurais (canvas 128×128) — padrão DOOM retrô.
 * ------------------------------------------------------------------------- */
const TEX = {
  startan: { base: '#7a2b20', dark: '#4a1510', rivet: '#c96f4a' },
  tech:    { base: '#4a5058', dark: '#2b2f36', rivet: '#8a93a0' },
  brick:   { base: '#5a2a1e', dark: '#3a1a12', rivet: '#7a4a3a' },
  emblem:  { base: '#2e3a2e', dark: '#1c241c', rivet: '#7a9a6a' },
  metal:   { base: '#6a7078', dark: '#3a3e44', rivet: '#a0a8b4' },
};

function makeCanvasTexture(name, w = 128, h = 128) {
  const canvas = document.createElement('canvas');
  canvas.width = w; canvas.height = h;
  const g = canvas.getContext('2d');
  const t = TEX[name] || TEX.tech;
  g.fillStyle = t.base;
  g.fillRect(0, 0, w, h);

  if (name === 'startan') {
    // painéis verticais com rebites nas bordas
    for (let x = 0; x < w; x += 16) {
      g.fillStyle = t.dark;
      g.fillRect(x, 0, 3, h);
      g.fillStyle = t.rivet;
      for (let y = 8; y < h; y += 16) {
        g.beginPath(); g.arc(x + 1.5, y, 1.6, 0, 7); g.fill();
        g.beginPath(); g.arc(x + 14.5, y, 1.6, 0, 7); g.fill();
      }
    }
    g.fillStyle = t.rivet;
    g.fillRect(0, 0, w, 4);
    g.fillRect(0, h - 4, w, 4);
  } else if (name === 'tech') {
    // placas metálicas + linhas de junção + parafusos
    for (let x = 0; x < w; x += 32) {
      g.fillStyle = t.dark;
      g.fillRect(x, 0, 2, h);
      for (let y = 8; y < h; y += 24) {
        g.fillStyle = t.rivet;
        g.beginPath(); g.arc(x + 1, y, 1.8, 0, 7); g.fill();
        g.beginPath(); g.arc(x + 31, y, 1.8, 0, 7); g.fill();
      }
    }
  } else if (name === 'brick') {
    // tijolos 16×8 com argamassa escura
    for (let y = 0; y < h; y += 8) {
      const off = (y / 8) % 2 === 0 ? 0 : 8;
      for (let x = -8; x < w; x += 16) {
        const bx = x + off;
        g.fillStyle = t.rivet; // argamassa
        g.fillRect(bx, y, 16, 1);
        g.fillRect(bx, y, 1, 8);
      }
    }
  } else if (name === 'emblem') {
    // painel escuro + emblema central (losango + círculo)
    g.fillStyle = t.dark;
    g.fillRect(0, 0, w, h);
    g.fillStyle = t.rivet;
    g.strokeStyle = t.rivet;
    g.lineWidth = 3;
    g.strokeRect(4, 4, w - 8, h - 8);
    g.beginPath(); g.moveTo(w / 2, 24); g.lineTo(w - 30, h / 2); g.lineTo(w / 2, h - 24); g.lineTo(30, h / 2); g.closePath(); g.fill();
    g.beginPath(); g.arc(w / 2, h / 2, 18, 0, 7); g.fill();
  } else {
    // metal liso com rebites de canto
    g.fillStyle = t.dark;
    g.fillRect(0, 0, w, 4); g.fillRect(0, h - 4, w, 4);
    g.fillRect(0, 0, 4, h); g.fillRect(w - 4, 0, 4, h);
    g.fillStyle = t.rivet;
    [[6, 6], [w - 6, 6], [6, h - 6], [w - 6, h - 6]].forEach(([x, y]) => {
      g.beginPath(); g.arc(x, y, 2, 0, 7); g.fill();
    });
  }

  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.magFilter = THREE.NearestFilter; // retrô: pixelado
  return tex;
}

/* Cache de texturas (uma por tipo). */
const texCache = new Map();
function getTexture(name) {
  if (!texCache.has(name)) texCache.set(name, makeCanvasTexture(name));
  return texCache.get(name);
}

/* Material MeshBasicMaterial — iluminação "falsa" embutida na textura (perf). */
function wallMaterial(name) {
  return new THREE.MeshBasicMaterial({ map: getTexture(name) });
}

/* ---------------------------------------------------------------------------
 * Acumulador de quads → BufferGeometry indexada (faces com normais + UV).
 * ------------------------------------------------------------------------- */
class QuadBuilder {
  constructor() {
    this.pos = [];
    this.nrm = [];
    this.uv = [];
    this.idx = [];
  }
  /* Adiciona um quad vertical (parede): centro (cx,cz), largura dw, altura dh,
   * y-base by, normal (nx,nz) e uv-variante face (0..1). */
  quad(cx, cz, dw, dh, by, nx, nz, v) {
    const i = this.pos.length / 3;
    const hw = dw / 2;
    // face frontal orientada pela normal
    const tx = -nz, tz = nx; // tangente
    const p = [
      cx - tx * hw, by,     cz - tz * hw,
      cx + tx * hw, by,     cz + tz * hw,
      cx + tx * hw, by + dh, cz + tz * hw,
      cx - tx * hw, by + dh, cz - tz * hw,
    ];
    this.pos.push(...p);
    for (let k = 0; k < 4; k++) this.nrm.push(nx, 0, nz);
    // UVs: face vertical divide a textura em 4 faixas (v) — melhor variedade
    const u0 = 0, u1 = dw, v0 = v * 0.25, v1 = v0 + 0.25;
    this.uv.push(u0, v0, u1, v0, u1, v1, u0, v1);
    this.idx.push(i, i + 1, i + 2, i, i + 2, i + 3);
  }
  /* Adiciona um quad horizontal (chão/teto): centro (cx,cz), tamanho (w,h),
   * y fixo, normal (0,±1,0), v-face. */
  hquad(cx, cz, w, h, y, ny, v) {
    const i = this.pos.length / 3;
    const hw = w / 2, hh = h / 2;
    this.pos.push(
      cx - hw, y, cz - hh,
      cx + hw, y, cz - hh,
      cx + hw, y, cz + hh,
      cx - hw, y, cz + hh,
    );
    for (let k = 0; k < 4; k++) this.nrm.push(0, ny, 0);
    this.uv.push(0, 0, w, 0, w, h, 0, h);
    this.idx.push(i, i + 1, i + 2, i, i + 2, i + 3);
  }
  build() {
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
    g.setAttribute('normal', new THREE.Float32BufferAttribute(this.nrm, 3));
    g.setAttribute('uv', new THREE.Float32BufferAttribute(this.uv, 2));
    g.setIndex(this.idx);
    return g;
  }
}

/* ---------------------------------------------------------------------------
 * Construtor do nível
 * ------------------------------------------------------------------------- */
export function buildLevel(map, THREE) {
  const L = C.LEVEL;
  const group = new THREE.Group();
  const wallH = L.wallHeight;
  const ceilY = L.ceilingY;

  // builders por textura de parede
  const wallBuilders = new Map(); // nome → QuadBuilder
  function wallB(name) {
    if (!wallBuilders.has(name)) wallBuilders.set(name, new QuadBuilder());
    return wallBuilders.get(name);
  }
  const floorB = new QuadBuilder();
  const ceilB = new QuadBuilder();

  const h = map.H, w = map.W;
  for (let r = 0; r < h; r++) {
    for (let c = 0; c < w; c++) {
      const ch = map.grid[r][c];
      const isWall = ch === '#';
      const cx = c + 0.5, cz = r + 0.5;
      const zname = map.zone(r, c);

      // chão e teto (todos os tipos)
      const ftex = zname === 'arena' ? 'emblem' : zname === 'entrada' ? 'startan' : zname === 'catacumbas' || zname === 'armadilha' ? 'brick' : 'tech';
      const ctex = ftex === 'emblem' ? 'metal' : ftex;
      floorB.hquad(cx, cz, 1, 1, 0, 1, 0);
      ceilB.hquad(cx, cz, 1, 1, ceilY, -1, 0);

      if (isWall) {
        const b = wallB(ftex === 'emblem' ? 'emblem' : ftex);
        const v = (r + c) % 4;
        if (c > 0 && !map.isSolid(r, c - 1)) b.quad(cx - 0.5, cz, 1, wallH, 0, -1, 0, v);          // oeste
        if (c < w - 1 && !map.isSolid(r, c + 1)) b.quad(cx + 0.5, cz, 1, wallH, 0, 1, 0, v);        // leste
        if (r > 0 && !map.isSolid(r - 1, c)) b.quad(cx, cz - 0.5, 1, wallH, 0, 0, -1, v);          // norte
        if (r < h - 1 && !map.isSolid(r + 1, c)) b.quad(cx, cz + 0.5, 1, wallH, 0, 0, 1, v);        // sul
      }
    }
  }

  // monta meshes das paredes (um por textura)
  for (const [name, b] of wallBuilders) {
    const m = new THREE.Mesh(b.build(), wallMaterial(name));
    m.matrixAutoUpdate = false;
    group.add(m);
  }

  // chão + teto
  group.add(new THREE.Mesh(floorB.build(), new THREE.MeshBasicMaterial({ map: getTexture('metal'), color: 0x8a8a94 })));
  const ceilMat = new THREE.MeshBasicMaterial({ map: getTexture('metal'), color: 0x55555c });
  group.add(new THREE.Mesh(ceilB.build(), ceilMat));

  // ---- portas ---------------------------------------------------------------
  const doorMeshes = [];
  for (const d of map.doors) {
    const geo = new THREE.BoxGeometry(1, L.doorHeight, 0.18);
    const mat = new THREE.MeshBasicMaterial({ map: getTexture('metal') });
    const m = new THREE.Mesh(geo, mat);
    m.position.set(d.c + 0.5, L.doorHeight / 2 - 0.02, d.r + 0.5);
    group.add(m);
    doorMeshes.push({ d, mesh: m });
  }
  // segredos = portas que sobem quando abertas
  for (const s of map.secrets) {
    const geo = new THREE.BoxGeometry(1, L.doorHeight, 0.18);
    const mat = new THREE.MeshBasicMaterial({ map: getTexture('brick') });
    const m = new THREE.Mesh(geo, mat);
    m.position.set(s.c + 0.5, L.doorHeight / 2 - 0.02, s.r + 0.5);
    group.add(m);
    doorMeshes.push({ d: s, mesh: m, isSecret: true });
  }

  // ---- saída ----------------------------------------------------------------
  let exitPos = null;
  for (const e of map.exits) {
    const px = e.c + 0.5, pz = e.r + 0.5;
    exitPos = { x: px, z: pz };
    // pilar emissivo + plano brilhante virado para o centro da arena
    const pillar = new THREE.Mesh(
      new THREE.CylinderGeometry(0.22, 0.34, 2.6, 10),
      new THREE.MeshBasicMaterial({ color: 0x88ff88 }),
    );
    pillar.position.set(px, 1.3, pz);
    group.add(pillar);
    const glow = new THREE.Mesh(
      new THREE.PlaneGeometry(0.9, 2.6),
      new THREE.MeshBasicMaterial({ color: 0x66ff66, transparent: true, opacity: 0.85 }),
    );
    glow.position.set(px, 1.3, pz + 0.5);
    group.add(glow);
  }

  // ---- lava ----------------------------------------------------------------
  const lavaMats = [];
  for (let r = 0; r < h; r++) {
    for (let c = 0; c < w; c++) {
      if (map.grid[r][c] !== '~') continue;
      const mat = new THREE.MeshBasicMaterial({
        color: 0xff5a00, transparent: true, opacity: 0.9,
      });
      const m = new THREE.Mesh(new THREE.PlaneGeometry(0.96, 0.96), mat);
      m.rotation.x = -Math.PI / 2;
      m.position.set(c + 0.5, 0.02, r + 0.5);
      group.add(m);
      lavaMats.push(mat);
    }
  }

  // ---- tochas (luz pontual + chama) ------------------------------------------
  const torchLights = [];
  for (const t of map.torches) {
    const x = t.x, z = t.z;
    const flame = new THREE.Mesh(
      new THREE.ConeGeometry(0.07, 0.35, 6),
      new THREE.MeshBasicMaterial({ color: 0xffaa33 }),
    );
    flame.position.set(x, 1.75, z);
    group.add(flame);
    // agrupa luzes: compartilha uma única PointLight a cada par (draw calls)
    if (torchLights.length < 6) {
      const light = new THREE.PointLight(0xff8844, 0.9, 9, 1.6);
      light.position.set(x, 1.9, z);
      group.add(light);
      torchLights.push({ light, base: 0.9, phase: Math.random() * 10 });
    }
  }

  // ---- update por frame ------------------------------------------------------
  let elapsed = 0;
  function update(dt) {
    elapsed += dt;
    // portas: sobe até doorHeight quando abertas (t: 0 fechada → 1 aberta)
    for (const { d, mesh, isSecret } of doorMeshes) {
      const target = (isSecret ? d.open : d.open) ? 1 : 0;
      d.t += (target - d.t) * Math.min(1, dt * C.LEVEL.doorSpeed);
      const yOpen = L.doorHeight / 2 - 0.02;
      const yClosed = isSecret ? yOpen : 0.02; // segredo desce, porta sobe
      const y = isSecret ? yClosed + (yOpen - yClosed) * d.t : yClosed + (yOpen - yClosed) * d.t;
      mesh.position.y = y;
      mesh.visible = d.t > 0.02;
    }
    // lava pulsa
    for (const m of lavaMats) m.color.setHSL(0.03 + 0.02 * Math.sin(elapsed * 2.2), 1, 0.55 + 0.08 * Math.sin(elapsed * 3.1));
    // tochas tremeluzem
    for (const tl of torchLights) {
      const n = Math.sin(elapsed * 11 + tl.phase) * 0.5 + Math.sin(elapsed * 23 + tl.phase * 2) * 0.5;
      tl.light.intensity = tl.base * (0.55 + 0.45 * n);
    }
  }

  return { group, update, doorMeshes, exitPos, torchLights };
}

export default { buildLevel, getTexture };

/* level.js — constrói a geometria do nível a partir do grid puro (map.js).
 * 🎨 Render: usa Three.js (CanvasTexture, BufferGeometry, PointLight).
 * Exporta buildLevel(map, THREE) → { group, update, doorMeshes, exitPos, torchLights }.
 */
import { C } from './constants.js';

/* ---------------------------------------------------------------------------
 * Texturas procedurais (canvas 128×128) — padrão DOOM retrô.
 * ------------------------------------------------------------------------- */
const TEX = {
  startan: { base: '#7a2b20', dark: '#4a1510', rivet: '#c96f4a' },
  tech:    { base: '#4a5058', dark: '#2b2f36', rivet: '#8a93a0' },
  brick:   { base: '#5a2a1e', dark: '#3a1a12', rivet: '#7a4a3a' },
  emblem:  { base: '#2e3a2e', dark: '#1c241c', rivet: '#7a9a6a' },
  metal:   { base: '#6a7078', dark: '#3a3e44', rivet: '#a0a8b4' },
};

function makeCanvasTexture(name, w = 128, h = 128) {
  const canvas = document.createElement('canvas');
  canvas.width = w; canvas.height = h;
  const g = canvas.getContext('2d');
  const t = TEX[name] || TEX.tech;
  g.fillStyle = t.base;
  g.fillRect(0, 0, w, h);

  if (name === 'startan') {
    // painéis verticais com rebites nas bordas
    for (let x = 0; x < w; x += 16) {
      g.fillStyle = t.dark;
      g.fillRect(x, 0, 3, h);
      g.fillStyle = t.rivet;
      for (let y = 8; y < h; y += 16) {
        g.beginPath(); g.arc(x + 1.5, y, 1.6, 0, 7); g.fill();
        g.beginPath(); g.arc(x + 14.5, y, 1.6, 0, 7); g.fill();
      }
    }
    g.fillStyle = t.rivet;
    g.fillRect(0, 0, w, 4);
    g.fillRect(0, h - 4, w, 4);
  } else if (name === 'tech') {
    // placas metálicas + linhas de junção + parafusos
    for (let x = 0; x < w; x += 32) {
      g.fillStyle = t.dark;
      g.fillRect(x, 0, 2, h);
      for (let y = 8; y < h; y += 24) {
        g.fillStyle = t.rivet;
        g.beginPath(); g.arc(x + 1, y, 1.8, 0, 7); g.fill();
        g.beginPath(); g.arc(x + 31, y, 1.8, 0, 7); g.fill();
      }
    }
  } else if (name === 'brick') {
    // tijolos 16×8 com argamassa escura
    for (let y = 0; y < h; y += 8) {
      const off = (y / 8) % 2 === 0 ? 0 : 8;
      for (let x = -8; x < w; x += 16) {
        const bx = x + off;
        g.fillStyle = t.rivet; // argamassa
        g.fillRect(bx, y, 16, 1);
        g.fillRect(bx, y, 1, 8);
      }
    }
  } else if (name === 'emblem') {
    // painel escuro + emblema central (losango + círculo)
    g.fillStyle = t.dark;
    g.fillRect(0, 0, w, h);
    g.fillStyle = t.rivet;
    g.strokeStyle = t.rivet;
    g.lineWidth = 3;
    g.strokeRect(4, 4, w - 8, h - 8);
    g.beginPath(); g.moveTo(w / 2, 24); g.lineTo(w - 30, h / 2); g.lineTo(w / 2, h - 24); g.lineTo(30, h / 2); g.closePath(); g.fill();
    g.beginPath(); g.arc(w / 2, h / 2, 18, 0, 7); g.fill();
  } else {
    // metal liso com rebites de canto
    g.fillStyle = t.dark;
    g.fillRect(0, 0, w, 4); g.fillRect(0, h - 4, w, 4);
    g.fillRect(0, 0, 4, h); g.fillRect(w - 4, 0, 4, h);
    g.fillStyle = t.rivet;
    [[6, 6], [w - 6, 6], [6, h - 6], [w - 6, h - 6]].forEach(([x, y]) => {
      g.beginPath(); g.arc(x, y, 2, 0, 7); g.fill();
    });
  }

  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.magFilter = THREE.NearestFilter; // retrô: pixelado
  return tex;
}

/* Cache de texturas (uma por tipo). */
const texCache = new Map();
function getTexture(name) {
  if (!texCache.has(name)) texCache.set(name, makeCanvasTexture(name));
  return texCache.get(name);
}

/* Material MeshBasicMaterial — iluminação "falsa" embutida na textura (perf). */
function wallMaterial(name) {
  return new THREE.MeshBasicMaterial({ map: getTexture(name) });
}

/* ---------------------------------------------------------------------------
 * Acumulador de quads → BufferGeometry indexada (faces com normais + UV).
 * ------------------------------------------------------------------------- */
class QuadBuilder {
  constructor() {
    this.pos = [];
    this.nrm = [];
    this.uv = [];
    this.idx = [];
  }
  /* Adiciona um quad vertical (parede): centro (cx,cz), largura dw, altura dh,
   * y-base by, normal (nx,nz) e uv-variante face (0..1). */
  quad(cx, cz, dw, dh, by, nx, nz, v) {
    const i = this.pos.length / 3;
    const hw = dw / 2;
    // face frontal orientada pela normal
    const tx = -nz, tz = nx; // tangente
    const p = [
      cx - tx * hw, by,     cz - tz * hw,
      cx + tx * hw, by,     cz + tz * hw,
      cx + tx * hw, by + dh, cz + tz * hw,
      cx - tx * hw, by + dh, cz - tz * hw,
    ];
    this.pos.push(...p);
    for (let k = 0; k < 4; k++) this.nrm.push(nx, 0, nz);
    // UVs: face vertical divide a textura em 4 faixas (v) — melhor variedade
    const u0 = 0, u1 = dw, v0 = v * 0.25, v1 = v0 + 0.25;
    this.uv.push(u0, v0, u1, v0, u1, v1, u0, v1);
    this.idx.push(i, i + 1, i + 2, i, i + 2, i + 3);
  }
  /* Adiciona um quad horizontal (chão/teto): centro (cx,cz), tamanho (w,h),
   * y fixo, normal (0,±1,0), v-face. */
  hquad(cx, cz, w, h, y, ny, v) {
    const i = this.pos.length / 3;
    const hw = w / 2, hh = h / 2;
    this.pos.push(
      cx - hw, y, cz - hh,
      cx + hw, y, cz - hh,
      cx + hw, y, cz + hh,
      cx - hw, y, cz + hh,
    );
    for (let k = 0; k < 4; k++) this.nrm.push(0, ny, 0);
    this.uv.push(0, 0, w, 0, w, h, 0, h);
    this.idx.push(i, i + 1, i + 2, i, i + 2, i + 3);
  }
  build() {
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
    g.setAttribute('normal', new THREE.Float32BufferAttribute(this.nrm, 3));
    g.setAttribute('uv', new THREE.Float32BufferAttribute(this.uv, 2));
    g.setIndex(this.idx);
    return g;
  }
}

/* ---------------------------------------------------------------------------
 * Construtor do nível
 * ------------------------------------------------------------------------- */
export function buildLevel(map, THREE) {
  const L = C.LEVEL;
  const group = new THREE.Group();
  const wallH = L.wallHeight;
  const ceilY = L.ceilingY;

  // builders por textura de parede
  const wallBuilders = new Map(); // nome → QuadBuilder
  function wallB(name) {
    if (!wallBuilders.has(name)) wallBuilders.set(name, new QuadBuilder());
    return wallBuilders.get(name);
  }
  const floorB = new QuadBuilder();
  const ceilB = new QuadBuilder();

  const h = map.H, w = map.W;
  for (let r = 0; r < h; r++) {
    for (let c = 0; c < w; c++) {
      const ch = map.grid[r][c];
      const isWall = ch === '#';
      const cx = c + 0.5, cz = r + 0.5;
      const zname = map.zone(r, c);

      // chão e teto (todos os tipos)
      const ftex = zname === 'arena' ? 'emblem' : zname === 'entrada' ? 'startan' : zname === 'catacumbas' || zname === 'armadilha' ? 'brick' : 'tech';
      const ctex = ftex === 'emblem' ? 'metal' : ftex;
      floorB.hquad(cx, cz, 1, 1, 0, 1, 0);
      ceilB.hquad(cx, cz, 1, 1, ceilY, -1, 0);

      if (isWall) {
        const b = wallB(ftex === 'emblem' ? 'emblem' : ftex);
        const v = (r + c) % 4;
        if (c > 0 && !map.isSolid(r, c - 1)) b.quad(cx - 0.5, cz, 1, wallH, 0, -1, 0, v);          // oeste
        if (c < w - 1 && !map.isSolid(r, c + 1)) b.quad(cx + 0.5, cz, 1, wallH, 0, 1, 0, v);        // leste
        if (r > 0 && !map.isSolid(r - 1, c)) b.quad(cx, cz - 0.5, 1, wallH, 0, 0, -1, v);          // norte
        if (r < h - 1 && !map.isSolid(r + 1, c)) b.quad(cx, cz + 0.5, 1, wallH, 0, 0, 1, v);        // sul
      }
    }
  }

  // monta meshes das paredes (um por textura)
  for (const [name, b] of wallBuilders) {
    const m = new THREE.Mesh(b.build(), wallMaterial(name));
    m.matrixAutoUpdate = false;
    group.add(m);
  }

  // chão + teto
  group.add(new THREE.Mesh(floorB.build(), new THREE.MeshBasicMaterial({ map: getTexture('metal'), color: 0x8a8a94 })));
  const ceilMat = new THREE.MeshBasicMaterial({ map: getTexture('metal'), color: 0x55555c });
  group.add(new THREE.Mesh(ceilB.build(), ceilMat));

  // ---- portas ---------------------------------------------------------------
  const doorMeshes = [];
  for (const d of map.doors) {
    const geo = new THREE.BoxGeometry(1, L.doorHeight, 0.18);
    const mat = new THREE.MeshBasicMaterial({ map: getTexture('metal') });
    const m = new THREE.Mesh(geo, mat);
    m.position.set(d.c + 0.5, L.doorHeight / 2 - 0.02, d.r + 0.5);
    group.add(m);
    doorMeshes.push({ d, mesh: m });
  }
  // segredos = portas que sobem quando abertas
  for (const s of map.secrets) {
    const geo = new THREE.BoxGeometry(1, L.doorHeight, 0.18);
    const mat = new THREE.MeshBasicMaterial({ map: getTexture('brick') });
    const m = new THREE.Mesh(geo, mat);
    m.position.set(s.c + 0.5, L.doorHeight / 2 - 0.02, s.r + 0.5);
    group.add(m);
    doorMeshes.push({ d: s, mesh: m, isSecret: true });
  }

  // ---- saída ----------------------------------------------------------------
  let exitPos = null;
  for (const e of map.exits) {
    const px = e.c + 0.5, pz = e.r + 0.5;
    exitPos = { x: px, z: pz };
    // pilar emissivo + plano brilhante virado para o centro da arena
    const pillar = new THREE.Mesh(
      new THREE.CylinderGeometry(0.22, 0.34, 2.6, 10),
      new THREE.MeshBasicMaterial({ color: 0x88ff88 }),
    );
    pillar.position.set(px, 1.3, pz);
    group.add(pillar);
    const glow = new THREE.Mesh(
      new THREE.PlaneGeometry(0.9, 2.6),
      new THREE.MeshBasicMaterial({ color: 0x66ff66, transparent: true, opacity: 0.85 }),
    );
    glow.position.set(px, 1.3, pz + 0.5);
    group.add(glow);
  }

  // ---- lava ----------------------------------------------------------------
  const lavaMats = [];
  for (let r = 0; r < h; r++) {
    for (let c = 0; c < w; c++) {
      if (map.grid[r][c] !== '~') continue;
      const mat = new THREE.MeshBasicMaterial({
        color: 0xff5a00, transparent: true, opacity: 0.9,
      });
      const m = new THREE.Mesh(new THREE.PlaneGeometry(0.96, 0.96), mat);
      m.rotation.x = -Math.PI / 2;
      m.position.set(c + 0.5, 0.02, r + 0.5);
      group.add(m);
      lavaMats.push(mat);
    }
  }

  // ---- tochas (luz pontual + chama) ------------------------------------------
  const torchLights = [];
  for (const t of map.torches) {
    const x = t.x, z = t.z;
    const flame = new THREE.Mesh(
      new THREE.ConeGeometry(0.07, 0.35, 6),
      new THREE.MeshBasicMaterial({ color: 0xffaa33 }),
    );
    flame.position.set(x, 1.75, z);
    group.add(flame);
    // agrupa luzes: compartilha uma única PointLight a cada par (draw calls)
    if (torchLights.length < 6) {
      const light = new THREE.PointLight(0xff8844, 0.9, 9, 1.6);
      light.position.set(x, 1.9, z);
      group.add(light);
      torchLights.push({ light, base: 0.9, phase: Math.random() * 10 });
    }
  }

  // ---- update por frame ------------------------------------------------------
  let elapsed = 0;
  function update(dt) {
    elapsed += dt;
    // portas: sobe até doorHeight quando abertas (t: 0 fechada → 1 aberta)
    for (const { d, mesh, isSecret } of doorMeshes) {
      const target = (isSecret ? d.open : d.open) ? 1 : 0;
      d.t += (target - d.t) * Math.min(1, dt * C.LEVEL.doorSpeed);
      const yOpen = L.doorHeight / 2 - 0.02;
      const yClosed = isSecret ? yOpen : 0.02; // segredo desce, porta sobe
      const y = isSecret ? yClosed + (yOpen - yClosed) * d.t : yClosed + (yOpen - yClosed) * d.t;
      mesh.position.y = y;
      mesh.visible = d.t > 0.02;
    }
    // lava pulsa
    for (const m of lavaMats) m.color.setHSL(0.03 + 0.02 * Math.sin(elapsed * 2.2), 1, 0.55 + 0.08 * Math.sin(elapsed * 3.1));
    // tochas tremeluzem
    for (const tl of torchLights) {
      const n = Math.sin(elapsed * 11 + tl.phase) * 0.5 + Math.sin(elapsed * 23 + tl.phase * 2) * 0.5;
      tl.light.intensity = tl.base * (0.55 + 0.45 * n);
    }
  }

  return { group, update, doorMeshes, exitPos, torchLights };
}

export default { buildLevel, getTexture };

