 */
import { C } from './constants.js';
import { stepPlayer, speed2D } from './physics.js';
import { moveVec } from './move.js';

export function createPlayer(engine, map) {
  const P = C.PLAYER;
  const s = map.spawn;
  const camera = engine.camera;

  const player = {
    x: s.x, y: 0, z: s.z,
    vx: 0, vy: 0, vz: 0,
    onGround: true,
    health: P.healthMax,
    armor: 0,
    invuln: 0,
    bob: 0,
    dead: false,
    kills: 0,
  };

  camera.position.set(s.x, P.eye, s.z);
  camera.rotation.set(0, P.spawnYaw, 0);

  function damage(amount) {
    if (player.dead || player.invuln > 0) return false;
    const absorbed = Math.min(player.armor, amount * P.armorAbsorb);
    player.armor -= absorbed;
    const real = amount - absorbed;
    player.health -= real;
    player.invuln = P.hitInvuln;
    if (player.health <= 0) {
      player.health = 0;
      player.dead = true;
    }
    return true;
  }

  function heal(amount) {
    player.health = Math.min(P.healthMax, player.health + amount);
  }

  function addArmor(amount) {
    player.armor = Math.min(P.armorMax, player.armor + amount);
  }

  function update(dt) {
    if (player.dead) {
      player.vy = 0;
      camera.rotation.z += dt * 1.2; // tomba ao morrer
      return;
    }
    const inp = engine.input;
    let ix = 0, iz = 0;
    if (inp.keys.has('KeyW')) iz += 1;
    if (inp.keys.has('KeyS')) iz -= 1;
    if (inp.keys.has('KeyA')) ix -= 1;
    if (inp.keys.has('KeyD')) ix += 1;
    const len = Math.hypot(ix, iz);
    if (len > 0) { ix /= len; iz /= len; }
    const mv = moveVec(camera.rotation.y, ix, iz);
    const run = inp.keys.has('ShiftLeft') || inp.keys.has('ShiftRight');
    const mag = inp.keys.has('KeyW') || inp.keys.has('KeyS') || inp.keys.has('KeyA') || inp.keys.has('KeyD') ? 1 : 0;

    stepPlayer(map, player, {
      dx: mv.x, dz: mv.z, mag, run,
      jump: engine.wasPressed('Space') || inp.keys.has('Space') && player.onGround,
    }, dt);

    if (player.invuln > 0) player.invuln -= dt;

    // view bob
    if (speed2D(player) > 0.3 && player.onGround) {
      player.bob += dt * P.bobFreq * Math.min(1, speed2D(player) / P.walk);
    }
    const bobY = Math.sin(player.bob * Math.PI * 2) * P.bobAmp;
    const bobX = Math.cos(player.bob * Math.PI) * P.bobAmp * 0.5;

    camera.position.set(player.x, P.eye + player.y + bobY, player.z);
    camera.position.x += bobX;
  }

  function isLookingAt(r, c) {
    const dx = r + 0.5 - player.x;
    const dz = c + 0.5 - player.z;
    const d = Math.hypot(dx, dz);
    if (d < 0.001) return true;
    const fy = camera.rotation.y;
    const ang = Math.atan2(dz, dx);
    let diff = ang - fy;
    while (diff > Math.PI) diff -= Math.PI * 2;
    while (diff < -Math.PI) diff += Math.PI * 2;
    return Math.abs(diff) < 0.9;
  }

  return {
    ...player,
    camera,
    update,
    damage,
    heal,
    addArmor,
    isLookingAt,
  };
}

export default createPlayer;

