/* weapons.js — viewmodels procedurais, recuo, muzzle flash, hitscan, rocket spawn.
 * 🎨 Render: usa THREE (malhas presas à câmera) + weapons-core.js (math pura).
 * Disparos de projétil delegam ao módulo de projectiles via hook.
 */
import * as THREE from 'three';
import { C } from './constants.js';
import { fireReady, canFire, consumeAmmo, spreadOffset, chaingunSpread } from './weapons-core.js';
import { raycastWall } from './map.js';

const KEYS = ['1', '2', '3', '4'];
const NAMES = ['pistol', 'shotgun', 'chaingun', 'rocket'];

export function createWeapons(engine, player, scene, hooks) {
  const ammo = { shell: C.WEAPONS.shotgun.ammoStart, bullet: C.WEAPONS.chaingun.ammoStart, rocket: C.WEAPONS.rocket.ammoStart };
  let current = 0;
  let sinceLast = 99;
  let kick = 0;
  let muzzleT = 0;
  let spin = 0;

  const viewGroup = new THREE.Group();
  engine.camera.add(viewGroup);
  scene.add(engine.camera);

  const materials = {
    dark: new THREE.MeshBasicMaterial({ color: 0x2a2d33 }),
    steel: new THREE.MeshBasicMaterial({ color: 0x6a7078 }),
    grip: new THREE.MeshBasicMaterial({ color: 0x4a3524 }),
    brass: new THREE.MeshBasicMaterial({ color: 0xb08a3a }),
  };

  function box(w, h, d, mat, x, y, z) {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), materials[mat]);
    m.position.set(x, y, z);
    return m;
  }

  function buildViewmodel(type) {
    const g = new THREE.Group();
    if (type === 'pistol') {
      g.add(box(0.09, 0.13, 0.3, 'dark', 0, 0, 0));
      g.add(box(0.05, 0.05, 0.12, 'steel', 0, 0.08, -0.2));
      g.add(box(0.1, 0.06, 0.08, 'grip', -0.02, -0.09, 0.08));
    } else if (type === 'shotgun') {
      g.add(box(0.16, 0.09, 0.55, 'steel', 0, 0, 0));
      g.add(box(0.08, 0.09, 0.45, 'dark', 0.09, 0, -0.1));
      g.add(box(0.09, 0.05, 0.05, 'brass', 0, 0.07, -0.26));
      g.add(box(0.1, 0.12, 0.14, 'grip', -0.01, -0.13, 0.22));
    } else if (type === 'chaingun') {
      g.add(box(0.12, 0.14, 0.5, 'dark', 0, 0, 0));
      g.add(new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 0.3, 6).rotateX(Math.PI / 2), materials.steel)).position.set(0, 0.05, -0.25);
      g.add(box(0.1, 0.07, 0.12, 'grip', 0, -0.12, 0.1));
    } else {
      g.add(new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.07, 0.5, 8).rotateX(Math.PI / 2), materials.dark));
      g.add(new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.14, 6).rotateX(Math.PI / 2), materials.steel)).position.set(0, 0, -0.3);
      g.add(box(0.02, 0.2, 0.12, 'steel', 0.09, 0, 0.1));
      g.add(box(0.02, 0.2, 0.12, 'steel', -0.09, 0, 0.1));
      g.add(box(0.1, 0.08, 0.1, 'grip', 0, -0.13, 0.18));
    }
    g.position.set(0.26, -0.24, -0.45);
    return g;
  }

  const viewmodels = NAMES.map((n) => {
    const g = buildViewmodel(n);
    g.visible = false;
    viewGroup.add(g);
    return g;
  });
  viewmodels[0].visible = true;

  const muzzle = new THREE.Mesh(
    new THREE.SphereGeometry(0.06, 6, 6),
    new THREE.MeshBasicMaterial({ color: 0xffcc55, transparent: true, opacity: 0.9 }),
  );
  muzzle.visible = false;
  viewGroup.add(muzzle);

  const camDir = () => {
    const e = new THREE.Euler(camera.rotation.x, camera.rotation.y, 0, 'YXZ');
    const q = new THREE.Quaternion().setFromEuler(e);
    const v = new THREE.Vector3(0, 0, -1).applyQuaternion(q);
    return v;
  };

  const camera = engine.camera;

  function hitscanDamage(w, count = 1) {
    const dir = camDir();
    const origin = { x: camera.position.x, y: camera.position.y, z: camera.position.z };
    for (let i = 0; i < count; i++) {
      const s = spreadOffset(chaingunSpread(w.spread, spin));
      const dx = dir.x + dir.x * s.a - dir.z * s.b;
      const dz = dir.z + dir.z * s.a + dir.x * s.b;
      const wallDist = raycastWall(hooks.map, origin.x, origin.z, dx, dz);
      for (const e of hooks.getEnemies()) {
        if (e.dead) continue;
        const ex = e.x - origin.x, ez = e.z - origin.z;
        const t = Math.max(0, Math.min(1, (ex * dx + ez * dz)));
        const px = origin.x + t * dx - e.x, pz = origin.z + t * dz - e.z;
        if (Math.hypot(px, pz) < 0.5 && t < wallDist) {
          e.takeDamage(w.damage * (0.8 + Math.random() * 0.4));
          hooks.impact(e.x, e.y + 1, e.z);
        }
      }
    }
  }

  function fire() {
    const w = C.WEAPONS[NAMES[current]];
    if (!canFire(w, ammo)) { hooks.noAmmo(); return; }
    if (!fireReady(w, sinceLast)) return;
    sinceLast = 0;
    ammo = consumeAmmo(w, ammo);
    kick = Math.min(1, kick + (w.rate < 0.15 ? 0.12 : 0.5));
    muzzleT = 0.045;
    if (current === 0) spin = 0;
    else spin = Math.min(1, spin + 0.25);
    hooks.shoot();
    if (NAMES[current] === 'rocket') {
      const dir = camDir();
      hooks.spawnProjectile({ x: camera.position.x + dir.x * 0.8, y: camera.position.y - 0.1, z: camera.position.z + dir.z * 0.8 }, dir);
    } else {
      hitscanDamage(w, NAMES[current] === 'shotgun' ? w.pellets : 1);
    }
  }

  function select(i) {
    if (i === current) return;
    current = i;
    viewmodels.forEach((g, k) => { g.visible = k === i; });
    kick = 0.3;
  }

  function update(dt) {
    sinceLast += dt;
    if (muzzleT > 0) {
      muzzleT -= dt;
      muzzle.visible = true;
      muzzle.position.set(0.02, 0.02, -0.62);
    } else muzzle.visible = false;

    kick = Math.max(0, kick - dt * 3.2);
    for (const g of viewmodels) {
      if (!g.visible) continue;
      g.position.z = -0.45 + kick * 0.28;
      g.position.y = -0.24 + Math.sin(player.bob * Math.PI * 2) * 0.008;
      g.rotation.x = kick * 0.25;
      if (NAMES[current] === 'chaingun') {
        g.rotation.z = Math.sin(performance.now() * 0.05) * 0.02;
      }
    }
    for (let i = 0; i < 4; i++) {
      if (engine.wasPressed(KEYS[i])) select(i);
    }
    if (engine.input.scroll !== 0) {
      select((current + (engine.input.scroll > 0 ? 1 : 3)) % 4);
    }
  }

  return {
    ammo,
    get current() { return current; },
    get name() { return NAMES[current]; },
    update,
    fire,
    select,
    getViewmodel: () => viewmodels[current],
  };
}

export default createWeapons;

