/* projectiles.js — pool de projéteis: foguetes do jogador + fireballs inimigas.
 * 🎨 Render: malhas Three (esfera/cone) + física simples sem gravidade.
 * Splash usa weapons-core.splashDamage (math pura).
 */
import * as THREE from 'three';
import { C } from './constants.js';
import { splashDamage, selfSplashDamage } from './weapons-core.js';

const POOL = 32;

export function createProjectiles(scene, hooks) {
  const rocketGeo = new THREE.ConeGeometry(0.08, 0.3, 6).rotateX(Math.PI / 2);
  const fireGeo = new THREE.SphereGeometry(0.16, 6, 6);
  const rocketMat = new THREE.MeshBasicMaterial({ color: 0xccaa44 });
  const fireMat = new THREE.MeshBasicMaterial({ color: 0xff6622, emissive: 0xff3300, emissiveIntensity: 0.6 });

  const items = [];
  for (let i = 0; i < POOL; i++) {
    const mesh = new THREE.Mesh(rocketGeo, rocketMat);
    mesh.visible = false;
    scene.add(mesh);
    items.push({ mesh, active: false, vx: 0, vz: 0, vy: 0, life: 0, owner: 'player', type: 'rocket' });
  }

  function spawn(type, x, y, z, dx, dz, owner = 'player') {
    const p = items.find((i) => !i.active);
    if (!p) return;
    p.active = true;
    p.type = type;
    p.owner = owner;
    const spd = type === 'rocket' ? C.WEAPONS.rocket.projSpeed : C.ENEMIES.imp.projSpeed;
    const len = Math.hypot(dx, dz) || 1;
    p.vx = dx / len * spd;
    p.vz = dz / len * spd;
    p.vy = 0;
    p.life = 4;
    p.mesh.geometry = type === 'rocket' ? rocketGeo : fireGeo;
    p.mesh.material = type === 'rocket' ? rocketMat : fireMat;
    p.mesh.position.set(x, y, z);
    p.mesh.visible = true;
  }

  function impact(p) {
    p.active = false;
    p.mesh.visible = false;
    if (p.owner === 'player') {
      const w = C.WEAPONS.rocket;
      const R = w.splash;
      for (const e of hooks.getEnemies()) {
        if (e.dead) continue;
        const d = Math.hypot(e.x - p.mesh.position.x, e.z - p.mesh.position.z);
        if (d < R) e.takeDamage(splashDamage(w, d));
      }
      const pl = hooks.getPlayer();
      const pd = Math.hypot(pl.x - p.mesh.position.x, pl.z - p.mesh.position.z);
      if (pd < R) hooks.damagePlayer(selfSplashDamage(w, pd));
      hooks.onImpact(p.mesh.position.x, p.mesh.position.y, p.mesh.position.z, 'rocket');
    } else {
