/* enemies.js — 4 tipos, FSM (idle→chase→attack→dead), LOS aggro, drops.
 * 🎨 Render: malhas Three low-poly (geometria compartilhada) + lógica pura (map.hasLOS).
 */
import * as THREE from 'three';
import { C } from './constants.js';
import { hasLOS, dist2D } from './map.js';
import { circleFree } from './move.js';

const { zombie, imp, demon, baron } = C.ENEMIES;

export function createEnemies(scene, map, hooks) {
  const list = [];

  const geo = {
    zombie: buildZombieGeo(),
    imp: buildImpGeo(),
    demon: buildDemonGeo(),
    baron: buildBaronGeo(),
  };

  function buildZombieGeo() {
    const g = new THREE.Group();
    const body = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.8, 0.3), new THREE.MeshBasicMaterial({ color: zombie.color }));
    body.position.y = 0.8;
    const head = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.28, 0.28), new THREE.MeshBasicMaterial({ color: 0x9a9088 }));
    head.position.y = 1.45;
    g.add(body, head);
    return g;
  }

  function buildImpGeo() {
    const g = new THREE.Group();
    const body = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.9, 0.4), new THREE.MeshBasicMaterial({ color: imp.color }));
    body.position.y = 0.9;
    const head = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.34, 0.3), new THREE.MeshBasicMaterial({ color: 0xa04a35 }));
    head.position.y = 1.55;
    const hornL = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.25, 4), new THREE.MeshBasicMaterial({ color: 0xccaa66 }));
    hornL.position.set(-0.12, 1.85, 0.05);
    const hornR = hornL.clone();
    hornR.position.x = 0.12;
    g.add(body, head, hornL, hornR);
    return g;
  }

  function buildDemonGeo() {
    const g = new THREE.Group();
    const body = new THREE.Mesh(new THREE.BoxGeometry(0.8, 0.6, 0.45), new THREE.MeshBasicMaterial({ color: demon.color }));
    body.position.y = 0.55;
    const head = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.4, 0.35), new THREE.MeshBasicMaterial({ color: 0xc04080 }));
    head.position.set(0, 1.1, 0.1);
    const jaw = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.12, 0.3), new THREE.MeshBasicMaterial({ color: 0xe080b0 }));
    jaw.position.set(0, 0.85, 0.3);
    g.add(body, head, jaw);
    return g;
  }

  function buildBaronGeo() {
    const g = new THREE.Group();
    const body = new THREE.Mesh(new THREE.BoxGeometry(0.7, 1.1, 0.45), new THREE.MeshBasicMaterial({ color: baron.color }));
    body.position.y = 1.1;
    const head = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.45, 0.4), new THREE.MeshBasicMaterial({ color: 0x3a8a44 }));
    head.position.y = 1.85;
    const hL = new THREE.Mesh(new THREE.ConeGeometry(0.08, 0.4, 4), new THREE.MeshBasicMaterial({ color: 0xddcc88 }));
    hL.position.set(-0.15, 2.25, 0.02);
    const hR = hL.clone();
    hR.position.x = 0.15;
    g.add(body, head, hL, hR);
    return g;
  }

  function spawnFromMap() {
    for (const e of map.enemies) {
      const cfg = C.ENEMIES[e.type];
      const mesh = geo[e.type].clone();
      mesh.position.set(e.x, 0, e.z);
      mesh.visible = true;
      scene.add(mesh);
      list.push({
        type: e.type, x: e.x, z: e.z, y: 0,
        hp: cfg.hp,
        speed: cfg.speed,
        state: 'idle',
        cooldown: Math.random() * 1,
        facing: Math.random() * Math.PI * 2,
        mesh,
        dead: false,
        aggroed: false,
        flashT: 0,
      });
    }
  }

  const R = (lo, hi) => lo + Math.random() * (hi - lo);

  function damageEnemy(en, dmg) {
    if (en.dead) return;
    en.hp -= dmg;
    en.flashT = 0.08;
    if (en.hp <= 0) {
      en.dead = true;
      en.mesh.visible = false;
      hooks.onKill(en, en.x, en.z);
    } else if (!en.aggroed) {
      en.aggroed = true; // dano sempre aggra
      en.state = 'chase';
    }
  }

  function fireball(en) {
    const pl = hooks.getPlayer();
    const dx = pl.x - en.x, dz = pl.z - en.z;
    hooks.spawnFireball(en.x, en.y + 1.4, en.z, dx, dz, 'enemy');
  }

  function hitscanZombie(en) {
    const pl = hooks.getPlayer();
    const dx = pl.x - en.x, dz = pl.z - en.z;
    const d = Math.hypot(dx, dz);
    if (d > 0.01 && !hasLOS(map, Math.floor(en.z), Math.floor(en.x), Math.floor(pl.z), Math.floor(pl.x))) return false;
    hooks.damagePlayer(R(zombie.damageMin, zombie.damageMax));
    return true;
  }

  function update(dt) {
    const pl = hooks.getPlayer();
    for (const en of list) {
      if (en.dead) continue;
      en.flashT -= dt;
      if (en.mesh.material && en.flashT > 0) en.mesh.material.color.setHex(0xffffff);
      else if (en.mesh.children?.[0]?.material && en.flashT > 0) en.mesh.children[0].material.color.setHex(0xffffff);
      else if (en.mesh.children?.[0]?.material) en.mesh.children[0].material.color.setHex(en.type === 'zombie' ? zombie.color : en.type === 'imp' ? imp.color : en.type === 'demon' ? demon.color : baron.color);

      const cfg = C.ENEMIES[en.type];
      const d = dist2D(en.x, en.z, pl.x, pl.z);
      const hasLOSEnemy = hasLOS(map, Math.floor(en.z), Math.floor(en.x), Math.floor(pl.z), Math.floor(pl.x));

      if (!en.aggroed) {
        if (d < C.PLAYER.aggroRange && hasLOSEnemy) {
          en.aggroed = true;
          en.state = 'chase';
        }
        continue;
      }

      en.cooldown -= dt;
      en.facing = Math.atan2(pl.z - en.z, pl.x - en.x);

      if (en.type === 'demon') {
        if (d > cfg.rangeMax) { moveToward(en, pl, dt); }
        else if (en.cooldown <= 0) {
          en.cooldown = cfg.cooldown;
          hooks.damagePlayer(R(cfg.damage, cfg.damage));
          hooks.meleeImpact(en.x, en.z);
        }
        continue;
      }

      if (d > cfg.rangeMax) {
        moveToward(en, pl, dt);
      } else if (d >= cfg.rangeMin && en.cooldown <= 0) {
        en.cooldown = cfg.cooldown;
        if (en.type === 'zombie') hitscanZombie(en);
        else if (en.type === 'imp') fireball(en);
        else if (en.type === 'baron') {
          fireball(en);
          setTimeout(() => { if (!en.dead) fireball(en); }, 250);
        }
      } else if (d < cfg.rangeMin) {
        moveToward(en, pl, dt);
      }
    }
  }

  function moveToward(en, pl, dt) {
    const cfg = C.ENEMIES[en.type];
    const dx = pl.x - en.x, dz = pl.z - en.z;
    const d = Math.hypot(dx, dz) || 1;
    const nx = en.x + dx / d * cfg.speed * dt;
    const nz = en.z + dz / d * cfg.speed * dt;
    if (circleFree(map, nx, en.z, 0.35)) en.x = nx;
    if (circleFree(map, en.x, nz, 0.35)) en.z = nz;
    en.mesh.position.set(en.x, en.y, en.z);
    en.mesh.rotation.y = Math.atan2(dz, dx);
  }

  spawnFromMap();

  return {
    list,
    update,
    damageEnemy,
    get count() { return list.filter((e) => !e.dead).length; },
  };
}

export default createEnemies;

