/* minimap.js — overlay canvas 2D: paredes, jogador, direção, inimigos vistos.
 * 🎨 Render: desenha a cada frame em canvas 2D (fog-of-war leve por fade).
 */
export function createMinimap(canvas, map, getState) {
  const ctx = canvas.getContext('2d');
  const scale = 5;
  const w = map.W * scale;
  const h = map.H * scale;
  canvas.width = w;
  canvas.height = h;

  function draw() {
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = 'rgba(10,12,18,0.82)';
    ctx.fillRect(0, 0, w, h);

    // paredes
    ctx.fillStyle = '#3a4050';
    for (let r = 0; r < map.H; r++) {
      for (let c = 0; c < map.W; c++) {
        if (map.cellType(r, c) === '#') ctx.fillRect(c * scale, r * scale, scale, scale);
      }
    }

    // portas (abertas = verde piscando)
    for (const d of map.doors) {
      ctx.fillStyle = d.open ? '#66ff66' : '#cc8833';
      ctx.fillRect(d.c * scale, d.r * scale, scale, scale);
    }

    // lava
    ctx.fillStyle = '#ff5522';
    for (let r = 0; r < map.H; r++) {
      for (let c = 0; c < map.W; c++) {
        if (map.cellType(r, c) === '~') ctx.fillRect(c * scale, r * scale, scale, scale);
      }
    }

    // saída
    for (const e of map.exits) {
      ctx.fillStyle = '#55ff55';
      ctx.fillRect(e.c * scale, e.r * scale, scale, scale);
    }

    const st = getState();
    if (!st) return;

    // inimigos vistos (LOS do jogador)
    ctx.fillStyle = '#ff4433';
    for (const e of st.enemies) {
      if (e.dead) continue;
      ctx.fillRect(e.x * scale - 1, e.z * scale - 1, 3, 3);
    }

    // jogador + direção
    const px = st.player.x * scale;
    const pz = st.player.z * scale;
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(px, pz, 2.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(px, pz);
    const yaw = st.player.camera.rotation.y;
    ctx.lineTo(px + Math.cos(yaw) * 8, pz + Math.sin(yaw) * 8);
    ctx.stroke();
  }

  return { draw, canvas };
}

export default createMinimap;

