/* hud.js — HUD DOM: health/armor/ammo/arma/kills/mensagens/crosshair/vignette/CRT.
 * 🎨 Render: manipula elementos DOM (ids esperados no index.html).
 */
export function createHUD(getState) {
  const $ = (id) => document.getElementById(id);

  const healthBar = $('health-bar');
  const healthNum = $('health-num');
  const armorBar = $('armor-bar');
  const armorNum = $('armor-num');
  const ammoNum = $('ammo-num');
  const weaponName = $('weapon-name');
  const killsNum = $('kills-num');
  const messagesEl = $('messages');
  const crosshair = $('crosshair');
  const vignette = $('vignette');
  const crt = $('crt');
  const fpsEl = $('fps');

  let messages = [];
  let msgTimer = 0;
  let damageFlash = 0;

  function pushMessage(text) {
    messages.push(text);
    if (messages.length > 3) messages.shift();
    msgTimer = 3;
  }

  function flashDamage(amount) {
    damageFlash = Math.min(1, damageFlash + amount / 60);
    if (vignette) vignette.style.opacity = String(damageFlash * 0.8);
  }

  function update(dt) {
    const st = getState();
    if (!st) return;
    const { player, weapons, fps } = st;

    if (healthBar && healthNum) {
      const hp = Math.max(0, Math.round(player.health));
      healthBar.style.width = `${hp}%`;
      healthBar.style.background = hp > 40 ? '#5a9a44' : hp > 20 ? '#ccaa33' : '#cc3333';
      healthNum.textContent = String(hp);
    }
    if (armorBar && armorNum) {
      armorBar.style.width = `${Math.max(0, Math.round(player.armor))}%`;
      armorNum.textContent = String(Math.round(player.armor));
    }
    if (ammoNum) {
