tool_input.content:
/* main.js — bootstrap: monta todos os módulos, FSM (menu/playing/gameover/win),
 * eventos (dano, kill, pickup, porta, lava, saída) e API de debug (QA).
 * window.__registerMod é definido no index.html (antes deste módulo rodar).
 */
import * as THREE from 'three';
import C from './constants.js';
import { makeMap, dist2D } from './map.js';
import { createEngine } from './engine.js';
import { buildLevel } from './level.js';
import { createPlayer } from './player.js';
import { createWeapons } from './weapons.js';
import { createProjectiles } from './projectiles.js';
import { createEnemies } from './enemies.js';
import { createParticles } from './particles.js';
import { createMinimap } from './minimap.js';
import { createHUD } from './hud.js';
import './audio.js';

const canvas = document.getElementById('game-canvas');
const engine = createEngine(canvas);
const map = makeMap();
const level = buildLevel(map, THREE);
engine.scene.add(level.group);

const player = createPlayer(engine, map);
const particles = createParticles(engine.scene);
const audio = window.__mods?.audio;

const projectiles = createProjectiles(engine.scene, {
  map,
  getPlayer: () => player,
  getEnemies: () => enemies.list,
  damagePlayer: (d) => applyDamage(d),
  onImpact: (x, y, z, type) => {
    if (type === 'rocket') {
      particles.fire(x, y, z, 14);
      particles.smoke(x, y, z, 8);
      audio?.play('explosion');
      engine.input.my += 4; engine.input.mx += (Math.random() - 0.5) * 8;
    } else {
      particles.fire(x, y, z, 8);
      audio?.play('hit');
    }
  },
  sparks: (x, y, z, n, color) => particles.sparks(x, y, z, n, color),
});

const enemies = createEnemies(engine.scene, map, {
  getPlayer: () => player,
  damagePlayer: (d) => applyDamage(d),
  spawnFireball: (x, y, z, dx, dz, owner) => projectiles.spawn('fireball', x, y, z, dx, dz, owner),
  meleeImpact: (x, z) => { particles.blood(x, 1, z, 6); audio?.play('hit'); },
  onKill: (en, x, z) => {
    player.kills += 1;
    particles.blood(x, 1, z, 10);
    audio?.play('kill');
    dropFrom(en, x, z);
  },
});

const weapons = createWeapons(engine, player, engine.scene, {
  map,
  getEnemies: () => enemies.list,
  shoot: () => audio?.play('shot'),
  noAmmo: () => audio?.play('noammo'),
  spawnProjectile: (o, dir) => projectiles.spawn('rocket', o.x, o.y, o.z, dir.x, dir.z),
  impact: (x, y, z) => { particles.sparks(x, y, z, 4); audio?.play('hit'); },
});

const minimap = createMinimap(document.getElementById('minimap'), map, () => ({
  player, enemies: enemies.list,
}));

const hud = createHUD(() => ({
  player, weapons,
  fps: engine.fps,
  locked: engine.input.locked,
}));

/* ---- pickups (meshes simples) -------------------------------------------- */
const pickupMeshes = [];
const pickupGeo = {
  health: new THREE.BoxGeometry(0.3, 0.3, 0.3),
  armor: new THREE.BoxGeometry(0.34, 0.34, 0.34),
  ammo: new THREE.BoxGeometry(0.26, 0.26, 0.26),
  weapon: new THREE.BoxGeometry(0.3, 0.2, 0.4),
};
const pickupMat = {
  health: new THREE.MeshBasicMaterial({ color: 0x44ff44 }),
  armor: new THREE.MeshBasicMaterial({ color: 0x44aaff }),
  ammo: new THREE.MeshBasicMaterial({ color: 0xffcc44 }),
  weapon: new THREE.MeshBasicMaterial({ color: 0xff8844 }),
};
for (const p of map.pickups) {
  const cat = p.type === 'health' ? 'health' : p.type === 'armor' ? 'armor' : p.type === 'shotgun' || p.type === 'chaingun' || p.type === 'rocket' ? 'weapon' : 'ammo';
  const mesh = new THREE.Mesh(pickupGeo[cat], pickupMat[cat]);
  mesh.position.set(p.x, 0.5, p.z);
  engine.scene.add(mesh);
  pickupMeshes.push({ ...p, cat, mesh });
}

function dropFrom(en, x, z) {
  const r = Math.random();
  if (r < C.PICKUPS.dropAmmoChance) {
    const type = en.type === 'baron' || en.type === 'demon' ? 'rocket' : r < C.PICKUPS.dropAmmoChance / 2 ? 'shell' : 'bullet';
    weapons.ammo[type] = Math.min(C.WEAPONS[type === 'shell' ? 'shotgun' : type === 'bullet' ? 'chaingun' : 'rocket'].ammoMax, (weapons.ammo[type] || 0) + C.PICKUPS.ammoAmounts[type]);
    hud.pushMessage(`+${C.PICKUPS.ammoAmounts[type]} ${type.toUpperCase()}`);
  } else if (r < C.PICKUPS.dropAmmoChance + C.PICKUPS.dropHealthChance) {
    player.heal(C.PICKUPS.health);
    hud.pushMessage(`+${C.PICKUPS.health} HEALTH`);
  }
}

/* ---- dano / morte / vitória ---------------------------------------------- */
function applyDamage(d) {
  if (player.dead) return;
  if (player.damage(d)) {
    hud.flashDamage(d);
    audio?.play('hurt');
  }
  if (player.dead) setState('gameover');
}

/* ---- FSM ------------------------------------------------------------------ */
let state = 'menu';
const screens = {
  menu: 'menu-screen',
  gameover: 'dead-screen',
  win: 'win-screen',
};
function setState(s) {
  state = s;
  for (const [k, id] of Object.entries(screens)) {
    document.getElementById(id).classList.toggle('show', k === s);
  }
  if (s === 'playing' && !engine.input.locked) engine.requestLock();
  if (s !== 'playing' && document.pointerLockElement) engine.exitLock();
}

document.getElementById('btn-start').addEventListener('click', () => {
  audio?.init();
  setState('playing');
});
document.getElementById('btn-restart').addEventListener('click', () => location.reload());
document.getElementById('btn-win').addEventListener('click', () => location.reload());

/* ---- portas (proximidade) ------------------------------------------------- */
function handleDoors(dt) {
  for (const d of map.doors) {
    const dist = dist2D(player.x, player.z, d.c + 0.5, d.r + 0.5);
    const shouldOpen = dist < 1.3;
    if (shouldOpen !== d.open) {
      d.open = shouldOpen;
      if (shouldOpen) audio?.play('door');
    }
  }
}

/* ---- saída / lava / pickups ------------------------------------------------ */
function handleWorld(dt) {
  if (level.exitPos && dist2D(player.x, player.z, level.exitPos.x, level.exitPos.z) < 1.2 && state === 'playing') {
    hud.pushMessage('EXIT REACHED — VICTORY');
    setTimeout(() => setState('win'), 600);
  }
  const r = Math.floor(player.z), c = Math.floor(player.x);
  if (map.isLava(r, c) && !player.dead) {
    player.health = Math.max(0, player.health - C.LEVEL.lavaDamage * dt);
    hud.flashDamage(C.LEVEL.lavaDamage * dt);
    if (player.health <= 0 && !player.dead) {
      player.dead = true;
      setState('gameover');
    }
  }
  for (const p of pickupMeshes) {
    if (p.taken) continue;
    const d = dist2D(player.x, player.z, p.x, p.z);
    if (d > 0.9) continue;
    p.taken = true;
    p.mesh.visible = false;
    audio?.play('pickup');
    if (p.type === 'health') {
      player.heal(C.PICKUPS.health);
      hud.pushMessage(`+${C.PICKUPS.health} HEALTH`);
    } else if (p.type === 'armor') {
      player.addArmor(C.PICKUPS.armor);
      hud.pushMessage(`+${C.PICKUPS.armor} ARMOR`);
    } else if (p.type === 'shotgun' || p.type === 'chaingun' || p.type === 'rocket') {
      const key = p.type;
      weapons.ammo[C.WEAPONS[key].ammoType] = Math.min(C.WEAPONS[key].ammoMax, (weapons.ammo[C.WEAPONS[key].ammoType] || 0) + C.WEAPONS[key].ammoStart);
      hud.pushMessage(`${key.toUpperCase()} ACQUIRED`);
    } else {
      const amount = C.PICKUPS.ammoAmounts[p.type];
      weapons.ammo[p.type] = Math.min(C.WEAPONS[p.type === 'bullet' ? 'chaingun' : p.type === 'shell' ? 'shotgun' : 'rocket'].ammoMax, (weapons.ammo[p.type] || 0) + amount);
      hud.pushMessage(`+${amount} ${p.type.toUpperCase()}`);
    }
  }
  // bobbing dos pickups
  for (const p of pickupMeshes) {
    if (!p.taken) p.mesh.rotation.y += dt * 2;
  }
}

/* ---- loop principal -------------------------------------------------------- */
let t = 0;
engine.start((dt) => {
  t += dt;
  if (state === 'playing') {
    player.update(dt);
    weapons.update(dt);
    enemies.update(dt);
    projectiles.update(dt);
    level.update(dt);
    handleDoors(dt);
    handleWorld(dt);
  } else {
    projectiles.update(dt);
    level.update(dt);
  }
  particles.update(dt);
  minimap.draw();
  hud.update(dt);
});

/* ---- API de debug (QA Playwright) ------------------------------------------ */
window.__game = {
  get state() { return state; },
  engine, map, player, weapons, enemies, projectiles, particles, level,
  setState,
  getState() {
    return {
      player,
      weapons: {
        current: weapons.current,
        name: weapons.name,
        ammo: weapons.ammo,
      },
      enemies: enemies.list.map((e) => ({ type: e.type, x: e.x, z: e.z, hp: e.hp, dead: e.dead })),
      fps: engine.fps.value,
      locked: engine.input.locked,
    };
  },
  damagePlayer: (d) => applyDamage(d),
  killAll() { enemies.list.forEach((e) => enemies.damageEnemy(e, 9999)); },
  giveAmmo(type, n) { weapons.ammo[type] = (weapons.ammo[type] || 0) + n; },
  setWeapon(i) { weapons.select(i); },
  teleport(x, z) { player.x = x; player.z = z; },
  toggleMute() { return audio?.toggleMute(); },
};

export default { engine, player };

