      player.addArmor(C.PICKUPS.armor);
      hud.pushMessage(`+${C.PICKUPS.armor} ARMOR`);
    } else if (p.type === 'shotgun' || p.type === 'chaingun' || p.type === 'rocket') {
      const key = p.type;
      weapons.ammo[C.WEAPONS[key].ammoType] = Math.min(C.WEAPONS[key].ammoMax, (weapons.ammo[C.WEAPONS[key].ammoType] || 0) + C.WEAPONS[key].ammoStart);
      hud.pushMessage(`${key.toUpperCase()} ACQUIRED`);
    } else {
      const amount = C.PICKUPS.ammoAmounts[p.type];
      weapons.ammo[p.type] = Math.min(C.WEAPONS[p.type === 'bullet' ? 'chaingun' : p.type === 'shell' ? 'shotgun' : 'rocket'].ammoMax, (weapons.ammo[p.type] || 0) + amount);
      hud.pushMessage(`+${amount} ${p.type.toUpperCase()}`);
    }
  }
  // bobbing dos pickups
  for (const p of pickupMeshes) {
    if (!p.taken) p.mesh.rotation.y += dt * 2;
  }
}

/* ---- loop principal -------------------------------------------------------- */
let t = 0;
engine.start((dt) => {
  t += dt;
  if (state === 'playing') {
    player.update(dt);
    weapons.update(dt);
    enemies.update(dt);
    projectiles.update(dt);
    level.update(dt);
    handleDoors(dt);
    handleWorld(dt);
  } else {
    projectiles.update(dt);
    level.update(dt);
  }
  particles.update(dt);
  minimap.draw();
  hud.update(dt);
});

/* ---- API de debug (QA Playwright) ------------------------------------------ */
window.__game = {
  get state() { return state; },
  engine, map, player, weapons, enemies, projectiles, particles, level,
  setState,
  getState() {
    return {
      player,
      weapons: {
        current: weapons.current,
        name: weapons.name,
        ammo: weapons.ammo,
      },
      enemies: enemies.list.map((e) => ({ type: e.type, x: e.x, z: e.z, hp: e.hp, dead: e.dead })),
      fps: engine.fps.value,
      locked: engine.input.locked,
    };
  },
  damagePlayer: (d) => applyDamage(d),
  killAll() { enemies.list.forEach((e) => enemies.damageEnemy(e, 9999)); },
  giveAmmo(type, n) { weapons.ammo[type] = (weapons.ammo[type] || 0) + n; },
  setWeapon(i) { weapons.select(i); },
  teleport(x, z) { player.x = x; player.z = z; },
  toggleMute() { return audio?.toggleMute(); },
};

export default { engine, player };

