tool_input.content:
/* style.css — HUD militar-retrô: fonte mono, barras âmbar/verde, CRT, telas FSM. */
* { margin: 0; padding: 0; box-sizing: border-box; }

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #0a0c10;
  font-family: 'Courier New', ui-monospace, monospace;
  user-select: none;
  -webkit-user-select: none;
}

#game-canvas {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

/* ---- CRT overlay ---------------------------------------------------------- */
#crt {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 5;
  background:
    repeating-linear-gradient(0deg, rgba(0, 0, 0, 0.12) 0 1px, transparent 1px 3px),
    radial-gradient(ellipse at center, transparent 55%, rgba(0, 0, 0, 0.35) 100%);
  mix-blend-mode: multiply;
}

/* ---- vignette de dano ------------------------------------------------------ */
#vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 6;
  opacity: 0;
  background: radial-gradient(ellipse at center, transparent 40%, rgba(180, 20, 20, 0.85) 100%);
  transition: opacity 0.1s linear;
}

/* ---- crosshair ------------------------------------------------------------- */
#crosshair {
  position: fixed;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  z-index: 7;
  color: #9fe89f;
  font-size: 22px;
  line-height: 1;
  text-shadow: 0 0 4px rgba(0, 0, 0, 0.8);
  pointer-events: none;
}

/* ---- HUD ------------------------------------------------------------------- */
#hud {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 8;
  color: #c8d0d8;
  text-shadow: 1px 1px 0 #000;
}

#top-left {
  position: absolute;
  top: 14px;
  left: 14px;
  background: rgba(8, 10, 14, 0.72);
  border: 1px solid #2a3038;
  padding: 10px 12px;
  min-width: 210px;
}

.stat-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
  font-size: 13px;
  letter-spacing: 1px;
}

.stat-row:last-child { margin-bottom: 0; }

.label {
  color: #8a93a0;
  width: 46px;
  flex-shrink: 0;
}

.bar-wrap {
  flex: 1;
  height: 12px;
  background: #14181e;
  border: 1px solid #2a3038;
  overflow: hidden;
}

.bar {
  height: 100%;
  width: 100%;
  background: #5a9a44;
  transition: width 0.15s ease-out;
}

.num {
  width: 34px;
  text-align: right;
  font-weight: bold;
  color: #e8eef4;
}

#top-right {
  position: absolute;
  top: 14px;
  right: 14px;
  text-align: right;
  background: rgba(8, 10, 14, 0.72);
  border: 1px solid #2a3038;
  padding: 10px 12px;
  min-width: 150px;
}

#weapon-name {
  font-size: 15px;
  font-weight: bold;
  color: #ffcc55;
  letter-spacing: 2px;
}

#ammo-num {
  font-size: 30px;
  font-weight: bold;
  color: #e8eef4;
  margin-top: 2px;
}

#fps {
  margin-top: 6px;
  font-size: 11px;
  color: #6a7380;
}

#messages {
  position: absolute;
  left: 50%;
  bottom: 120px;
  transform: translateX(-50%);
  text-align: center;
  font-size: 15px;
  color: #ffe9a0;
  text-shadow: 1px 1px 2px #000;
}

#messages div { margin-bottom: 4px; }

#minimap {
  position: absolute;
  left: 14px;
  bottom: 14px;
  border: 1px solid #2a3038;
  background: rgba(8, 10, 14, 0.72);
  image-rendering: pixelated;
}

/* ---- telas FSM -------------------------------------------------------------- */
.screen {
  position: fixed;
  inset: 0;
  z-index: 20;
  display: none;
  align-items: center;
  justify-content: center;
  background: rgba(4, 6, 10, 0.82);
}

.screen.show { display: flex; }

.panel {
  text-align: center;
  background: rgba(10, 14, 20, 0.92);
  border: 2px solid #3a4050;
  padding: 40px 56px;
  max-width: 520px;
  box-shadow: 0 0 40px rgba(0, 0, 0, 0.8);
}

.panel h1 {
  font-size: 42px;
  letter-spacing: 6px;
  color: #ffcc55;
  text-shadow: 0 0 12px rgba(255, 204, 85, 0.4);
  margin-bottom: 8px;
}

.panel p {
  color: #8a93a0;
  margin-bottom: 18px;
  font-size: 14px;
}

.panel ul {
  list-style: none;
  margin: 0 auto 22px;
  text-align: left;
  color: #a8b0b8;
  font-size: 13px;
  line-height: 1.7;
}

.panel button {
  font-family: inherit;
  font-size: 18px;
  font-weight: bold;
  letter-spacing: 3px;
  color: #0a0c10;
  background: #ffcc55;
  border: none;
  padding: 12px 34px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.panel button:hover { background: #ffe080; transform: scale(1.04); }
.panel button:active { transform: scale(0.98); }

#dead-screen .panel h1 { color: #cc3333; text-shadow: 0 0 12px rgba(204, 51, 51, 0.5); }
#win-screen .panel h1 { color: #55cc55; text-shadow: 0 0 12px rgba(85, 204, 85, 0.5); }

